                mChoicesSpinner.setEnabled(false);
                mSelfDefinedValue.setEnabled(true);
                mSelfDefinedValue.setHint("integer");
                break;
            case ContextType.TIME:
                mChoicesSpinner.setEnabled(false);
                mSelfDefinedValue.setEnabled(true);
                mSelfDefinedValue.setHint("hh:mm:ss");
                break;
