                            dialog.cancel();
                        }
                    });
                    AlertDialog alert = builder.create();
                    alert.show();
                }
            } else {
                Toast.makeText(getApplicationContext(), "Invalid format!", Toast.LENGTH_SHORT).show();
            }
        }
    }
}

